<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Formula;

use DateTimeImmutable;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\UserFederatedIdentity;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityCreatedAtVO;

class CreatedAtCalculator
{
    public static function calculateCreatedAt(?UserFederatedIdentity $original = null): ?UserFederatedIdentityCreatedAtVO
    {
        return $original ? $original->createdAt() : UserFederatedIdentityCreatedAtVO::from(new DateTimeImmutable('now'));
    }
}
